    ['นำเสนอข้อมูลตามความเป็นจริง','ไม่กล่าวอ้างคุณภาพหรือการใช้งานสินค้า รวมถึงผลตอบแทน เกินความเป็นจริงหรือแตกต่างจากที่บริษัทกำหนด'],
    ['จำหน่ายตามราคาและรายการส่งเสริมการขาย','ไม่ขายผิดราคา หรือเสนอผลประโยชน์นอกเหนือจากแผนการตลาดและรายการส่งเสริมการขายของบริษัท เพื่อจูงใจให้ซื้อสินค้าหรือสมัครสมาชิก'],
    ['ดำเนินธุรกิจตามแนวทางบริษัท','มุ่งนำเสนอผลิตภัณฑ์แก่ผู้บริโภคและผู้สนใจธุรกิจ ไม่ชักชวนสมาชิกระดมเงินทุนหรือดำเนินธุรกิจในลักษณะแชร์ลูกโซ่'],
    ['เคารพสายงานและเพื่อนร่วมอาชีพ','ไม่ยุยงหรือส่งเสริมให้สมาชิกจากสายงานอื่นย้ายเข้าสู่สายงานตนเอง และไม่กล่าวร้ายบริษัทเพื่อนร่วมอาชีพจนก่อให้เกิดความเสียหาย'],
    ['ไม่ดำเนินธุรกิจขัดกับข้อกำหนดบริษัท','ไม่แสดงตนเป็นตัวแทนหรือดำเนินธุรกิจเกี่ยวกับสินค้าผิดจากที่บริษัทกำหนด รวมถึงธุรกิจอื่นที่ถือเป็นคู่แข่งขันกับบริษัท'],
    ['รักษาคุณธรรมและภาพลักษณ์','ประพฤติตนตามศีลธรรมและประเพณีอันดี หมั่นศึกษาความรู้ และรักษาเกียรติศักดิ์ศรี เพื่อส่งเสริมภาพลักษณ์ของสมาชิกและบริษัท'],
]; ?>
<div class="sn-ethics-grid"><?php foreach($principles as $i=>[$heading,$text]): ?><section class="sn-ethics-rule"><span class="sn-ethics-number" aria-hidden="true"><?= $i+1 ?></span><h3><?= $i+1 ?>. <?= esc($heading) ?></h3><p><?= esc($text) ?></p></section><?php endforeach ?>
<section class="sn-ethics-rule"><span class="sn-ethics-number" aria-hidden="true">8</span><h3>8. มาตรการเมื่อฝ่าฝืนจรรยาบรรณ</h3><ol><li><strong>ครั้งที่ 1:</strong> ตักเตือนด้วยวาจา</li><li><strong>ครั้งที่ 2:</strong> ตักเตือนเป็นลายลักษณ์อักษร และหยุดจ่ายคอมมิชชันทั้งหมดตามระยะเวลาที่บริษัทกำหนด โดยยึดคำตัดสินของบริษัทเป็นที่สุดตามประกาศ</li><li><strong>ครั้งที่ 3:</strong> ยกเลิกการเป็นสมาชิกของบริษัท</li></ol></section></div>
<aside class="sn-ethics-reference" aria-label="ข้อมูลอ้างอิง"><p><strong>ข้อมูลอ้างอิงตามภาพต้นฉบับ:</strong> คู่มือธุรกิจ หน้า 17<br><strong>เลขที่ใบอนุญาตที่ระบุในภาพ:</strong> สคบ. 59040300041</p><p>ข้อความนี้เรียบเรียงจากประกาศที่ให้มา โปรดศึกษาข้อกำหนดฉบับเต็มในคู่มือธุรกิจของบริษัท</p></aside>
